package com.nexodb.ui;

import com.nexodb.db.DataQualityService;
import com.nexodb.db.DataQualityService.*;
import com.nexodb.db.JdbcSession;
import com.nexodb.util.AuditLog;
import com.nexodb.util.BackgroundOperations;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import javax.swing.table.TableColumn;
import java.awt.*;
import java.util.List;
import java.util.*;
import java.util.concurrent.CancellationException;
import static com.nexodb.util.I18n.tr;

/** Safe, preview-first data profiling, masking and test data workspace. */
public final class DataQualityPanel extends JPanel {
    private final JdbcSession session;private final String database;private final JComboBox<String> tables=new JComboBox<>();private final JButton refresh=UiLanguage.button("Actualizar tablas"),cancel=UiLanguage.button("Cancelar");private final JLabel status=new JLabel(tr("Leyendo tablas…"));
    private final DefaultTableModel profileModel=readOnly(tr("Columna"),tr("Tipo"),tr("NULL"),tr("Vacíos"),tr("Distintos"),tr("Mínimo"),tr("Máximo"),tr("Longitud máx."));
    private final DefaultTableModel rulesModel=new DefaultTableModel(new Object[]{tr("Columna"),tr("Tipo"),tr("Regla"),tr("Valor fijo")},0){public boolean isCellEditable(int r,int c){return c>=2;}};
    private final DefaultTableModel maskModel=readOnly();private final DefaultTableModel generatedModel=new DefaultTableModel();
    private final JTable profileTable=new JTable(profileModel),rulesTable=new JTable(rulesModel),maskTable=new JTable(maskModel),generatedTable=new JTable(generatedModel);
    private final JButton analyze=UiLanguage.button("Analizar calidad"),previewMask=UiLanguage.button("Vista previa"),applyMask=UiLanguage.button("Aplicar filas revisadas"),generate=UiLanguage.button("Generar vista previa"),insert=UiLanguage.button("Insertar filas revisadas");
    private final JSpinner maskLimit=new JSpinner(new SpinnerNumberModel(25,1,500,1)),generateCount=new JSpinner(new SpinnerNumberModel(10,1,500,1));
    private final JLabel profileSummary=new JLabel(tr("El análisis es de solo lectura.")),maskWarning=new JLabel(tr("Vista previa obligatoria. Nunca se modifican claves primarias.")),generateWarning=new JLabel(tr("Los valores se pueden editar antes de insertarlos."));
    private volatile SwingWorker<?,?> worker;private volatile DataQualityService.Control cancelled=new DataQualityService.Control();private volatile BackgroundOperations.Operation operation;private Table current;private MaskPreview currentMask;private GeneratedPreview currentGenerated;

    public DataQualityPanel(JdbcSession session,String database){super(new BorderLayout(8,8));this.session=session;this.database=database;setName("data-quality-panel");setBorder(new EmptyBorder(10,10,10,10));
        JToolBar top=new JToolBar();top.setFloatable(false);top.add(new JLabel(session.profile().name()+" · "+database+"   "));tables.setName("quality-table-selector");tables.setPrototypeDisplayValue("tabla_con_nombre_muy_largo_000");tables.setMaximumSize(new Dimension(330,28));top.add(tables);top.add(refresh);top.add(cancel);top.addSeparator();top.add(status);add(top,BorderLayout.NORTH);
        JTabbedPane tabs=new JTabbedPane();tabs.addTab(tr("Calidad y perfil"),qualityTab());tabs.addTab(tr("Enmascaramiento"),maskTab());tabs.addTab(tr("Datos de prueba"),generatorTab());add(tabs);
        cancel.setEnabled(false);applyMask.setEnabled(false);insert.setEnabled(false);refresh.addActionListener(e->loadTables());tables.addActionListener(e->{if(tables.getSelectedItem()!=null)loadDescription();});analyze.addActionListener(e->analyze());previewMask.addActionListener(e->previewMask());applyMask.addActionListener(e->applyMask());generate.addActionListener(e->generate());insert.addActionListener(e->insert());cancel.addActionListener(e->cancel());
        loadTables();
    }
    public JdbcSession origin(){return session;}
    public String database(){return database;}
    private JPanel qualityTab(){JPanel panel=new JPanel(new BorderLayout(6,6));JToolBar bar=new JToolBar();bar.setFloatable(false);analyze.setIcon(IconFactory.of(IconFactory.Kind.SEARCH,16));bar.add(analyze);bar.addSeparator();bar.add(profileSummary);panel.add(bar,BorderLayout.NORTH);configure(profileTable);panel.add(new JScrollPane(profileTable));JLabel note=note("Calcula total, NULL, vacíos, distintos, mínimos, máximos y longitud. Se ejecuta en una conexión auxiliar y puede cancelarse.");panel.add(note,BorderLayout.SOUTH);return panel;}
    private JPanel maskTab(){JPanel panel=new JPanel(new BorderLayout(6,6));configure(rulesTable);configure(maskTable);JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,new JScrollPane(rulesTable),new JScrollPane(maskTable));split.setResizeWeight(.42);split.setDividerLocation(230);panel.add(split);JToolBar bar=new JToolBar();bar.setFloatable(false);bar.add(new JLabel(tr("Filas de muestra: ")));bar.add(maskLimit);bar.add(previewMask);bar.add(applyMask);bar.addSeparator();bar.add(maskWarning);panel.add(bar,BorderLayout.NORTH);panel.add(note("La aplicación usa una transacción y la clave primaria completa. Si una fila cambió después de la vista previa, todo se revierte."),BorderLayout.SOUTH);return panel;}
    private JPanel generatorTab(){JPanel panel=new JPanel(new BorderLayout(6,6));configure(generatedTable);panel.add(new JScrollPane(generatedTable));JToolBar bar=new JToolBar();bar.setFloatable(false);bar.add(new JLabel(tr("Filas: ")));bar.add(generateCount);bar.add(generate);bar.add(insert);bar.addSeparator();bar.add(generateWarning);panel.add(bar,BorderLayout.NORTH);panel.add(note("Las columnas autoincrementales, generadas o con valor predeterminado se omiten. Revisa restricciones y claves foráneas antes de insertar."),BorderLayout.SOUTH);return panel;}
    private static JLabel note(String text){JLabel label=new JLabel(tr(text));label.setIcon(IconFactory.of(IconFactory.Kind.INFO,15));return label;}
    private static DefaultTableModel readOnly(Object...columns){return new DefaultTableModel(columns,0){public boolean isCellEditable(int r,int c){return false;}};}
    private static void configure(JTable table){table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);table.setRowHeight(25);table.setAutoCreateRowSorter(true);UiLanguage.headers(table);}

    private void loadTables(){run("Leyendo tablas",false,()->{try(JdbcSession.ReadLease lease=session.borrowReadOnly()){return DataQualityService.tables(lease.session().connection(),session.profile().type(),database);}},value->{String selected=Objects.toString(tables.getSelectedItem(),"");tables.removeAllItems();for(String name:cast(value))tables.addItem(name);if(!selected.isBlank())tables.setSelectedItem(selected);if(tables.getSelectedItem()==null&&tables.getItemCount()>0)tables.setSelectedIndex(0);status.setText(tr("%s tablas disponibles",tables.getItemCount()));SwingUtilities.invokeLater(this::loadDescription);});}
    private void loadDescription(){String name=Objects.toString(tables.getSelectedItem(),"");if(name.isBlank())return;run("Leyendo estructura",false,()->{try(JdbcSession.ReadLease lease=session.borrowReadOnly()){return DataQualityService.describe(lease.session().connection(),session.profile().type(),database,name);}},value->{current=(Table)value;currentMask=null;currentGenerated=null;profileModel.setRowCount(0);maskModel.setDataVector(new Object[0][0],new Object[0]);generatedModel.setDataVector(new Object[0][0],new Object[0]);rulesModel.setRowCount(0);for(Column column:current.columns())if(column.writable()&&!column.primaryKey())rulesModel.addRow(new Object[]{column.name(),column.typeName(),MaskRule.CONSERVAR,""});TableColumn rule=rulesTable.getColumnModel().getColumn(2);rule.setCellEditor(new DefaultCellEditor(new JComboBox<>(MaskRule.values())));applyMask.setEnabled(false);insert.setEnabled(false);maskWarning.setText(current.primaryKeys().isEmpty()?tr("Bloqueado: esta tabla no tiene clave primaria."):tr("Vista previa obligatoria · Clave: ")+String.join(", ",current.primaryKeys()));status.setText(tr("Estructura cargada: ")+name);});}
    private void analyze(){Table table=required();if(table==null)return;run("Analizar calidad",true,()->{try(JdbcSession.ReadLease lease=session.borrowReadOnly()){return DataQualityService.profile(lease.session().connection(),table,cancelled);}},value->{Profile profile=(Profile)value;profileModel.setRowCount(0);for(ColumnProfile column:profile.columns())profileModel.addRow(new Object[]{column.name(),column.type(),column.nulls(),column.empty(),column.distinct(),column.minimum(),column.maximum(),column.maximumLength()});profileSummary.setText(tr("Filas: ")+profile.rows()+tr(" · Columnas: ")+profile.columns().size());status.setText(tr("Análisis terminado"));});}
    private void previewMask(){Table table=required();if(table==null)return;stopEditing(rulesTable);List<MaskSelection> selections=new ArrayList<>();for(int row=0;row<rulesModel.getRowCount();row++){MaskRule rule=(MaskRule)rulesModel.getValueAt(row,2);selections.add(new MaskSelection(String.valueOf(rulesModel.getValueAt(row,0)),rule,Objects.toString(rulesModel.getValueAt(row,3),"")));}run("Vista previa de enmascaramiento",true,()->{try(JdbcSession.ReadLease lease=session.borrowReadOnly()){return DataQualityService.previewMask(lease.session().connection(),table,selections,(Integer)maskLimit.getValue(),cancelled);}},value->{currentMask=(MaskPreview)value;Object[] columns=new Object[currentMask.columns().size()*2];for(int i=0;i<currentMask.columns().size();i++){columns[i*2]=currentMask.columns().get(i)+" · "+tr("actual");columns[i*2+1]=currentMask.columns().get(i)+" · "+tr("nuevo");}Object[][] rows=new Object[currentMask.original().size()][columns.length];for(int r=0;r<rows.length;r++)for(int c=0;c<currentMask.columns().size();c++){rows[r][c*2]=currentMask.original().get(r).get(c);rows[r][c*2+1]=currentMask.masked().get(r).get(c);}maskModel.setDataVector(rows,columns);applyMask.setEnabled(!rowsIsEmpty(rows));maskWarning.setText(tr("Solo vista previa · %s filas revisables",rows.length));status.setText(tr("Vista previa lista; aún no se modificó ningún dato."));});}
    private void applyMask(){if(currentMask==null||!LicenseGate.ensure(this))return;if(JOptionPane.showConfirmDialog(this,tr("Se actualizarán únicamente las filas visibles y revisadas, dentro de una transacción. ¿Continuar?"),tr("Aplicar enmascaramiento"),JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE)!=JOptionPane.YES_OPTION)return;MaskPreview preview=currentMask;String scope=database+"."+preview.table().name(),subject=preview.columns().toString()+"|"+preview.masked().size();run("Aplicar enmascaramiento",true,()->audited("DATA_MASK",scope,subject,()->DataQualityService.applyMask(session.connection(),preview,cancelled)),value->{int count=(Integer)value;currentMask=null;applyMask.setEnabled(false);status.setText(tr("Enmascaramiento aplicado: %s filas",count));JOptionPane.showMessageDialog(this,tr("Se actualizaron %s filas correctamente.",count));});}
    private void generate(){Table table=required();if(table==null)return;currentGenerated=DataQualityService.generate(table,(Integer)generateCount.getValue());generatedModel.setDataVector(currentGenerated.rows().stream().map(List::toArray).toArray(Object[][]::new),currentGenerated.columns().toArray());insert.setEnabled(!currentGenerated.rows().isEmpty());status.setText(tr("Datos de prueba generados en memoria; revisa o edita antes de insertar."));}
    private void insert(){if(currentGenerated==null||!LicenseGate.ensure(this))return;stopEditing(generatedTable);List<List<Object>> rows=new ArrayList<>();for(int r=0;r<generatedModel.getRowCount();r++){List<Object> row=new ArrayList<>();for(int c=0;c<generatedModel.getColumnCount();c++)row.add(generatedModel.getValueAt(r,c));rows.add(row);}GeneratedPreview preview=new GeneratedPreview(currentGenerated.table(),currentGenerated.columns(),rows);if(JOptionPane.showConfirmDialog(this,tr("Se insertarán %s filas revisadas dentro de una transacción. ¿Continuar?",rows.size()),tr("Insertar datos de prueba"),JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE)!=JOptionPane.YES_OPTION)return;String scope=database+"."+preview.table().name(),subject=preview.columns().toString()+"|"+rows.size();run("Insertar datos de prueba",true,()->audited("DATA_GENERATE",scope,subject,()->DataQualityService.insertGenerated(session.connection(),preview,cancelled)),value->{int count=(Integer)value;currentGenerated=null;insert.setEnabled(false);status.setText(tr("Datos de prueba insertados: %s filas",count));JOptionPane.showMessageDialog(this,tr("Se insertaron %s filas correctamente.",count));});}
    private Table required(){if(current==null)JOptionPane.showMessageDialog(this,tr("Selecciona una tabla y espera a que termine de leer su estructura."));return current;}
    public void disposePanel(){cancel();}
    private void cancel(){cancelled.cancel();SwingWorker<?,?> active=worker;if(active!=null)active.cancel(true);}
    private interface Work {Object run()throws Exception;}private interface Success {void accept(Object value);}
    private Object audited(String action,String scope,String subject,Work work)throws Exception{try{Object result=work.run();AuditLog.configured().record(action,session.profile().name(),scope,"OK",subject);return result;}catch(Exception|Error failure){AuditLog.configured().record(action,session.profile().name(),scope,"FAILED",subject);throw failure;}}
    private void run(String label,boolean tracked,Work work,Success success){if(worker!=null&&!worker.isDone())return;cancelled=new DataQualityService.Control();setBusy(true);BackgroundOperations.Operation op=tracked?BackgroundOperations.create(BackgroundOperations.Kind.MIGRATION,tr(label),session.profile().name(),this::cancel,()->SwingUtilities.invokeLater(()->{})):null;operation=op;worker=new SwingWorker<>(){protected Object doInBackground()throws Exception{if(op!=null)op.awaitTurn();return work.run();}protected void done(){try{Object value=get();if(op!=null)op.complete(tr("Operación terminada"));success.accept(value);}catch(Exception failure){Throwable cause=root(failure);if(op!=null){if(cause instanceof CancellationException||isCancelled())op.cancelled(tr("Cancelada"));else op.fail(cause);}if(!(cause instanceof CancellationException)){status.setText(tr("No se pudo completar la operación."));JOptionPane.showMessageDialog(DataQualityPanel.this,Objects.toString(cause.getMessage(),cause.toString()),tr("Calidad de datos"),JOptionPane.ERROR_MESSAGE);}}finally{worker=null;operation=null;setBusy(false);}}};worker.execute();}
    private void setBusy(boolean value){refresh.setEnabled(!value);tables.setEnabled(!value);analyze.setEnabled(!value);previewMask.setEnabled(!value);generate.setEnabled(!value);cancel.setEnabled(value);if(value)status.setText(tr("Procesando…"));}
    private static Throwable root(Throwable value){Throwable result=value;while(result.getCause()!=null)result=result.getCause();return result;}
    private static void stopEditing(JTable table){if(table.isEditing())table.getCellEditor().stopCellEditing();}
    @SuppressWarnings("unchecked")private static List<String> cast(Object value){return (List<String>)value;}
    private static boolean rowsIsEmpty(Object[][] rows){return rows.length==0;}
}
